fn solve(r1: i8, c1: i8, r2: i8, c2: i8) -> Vec<i8> {
    // Rook moves:
    // 0 if same square,
    // 1 if same row or column,
    // otherwise 2.
    let rook = if r1 == r2 && c1 == c2 {
        0
    } else if r1 == r2 || c1 == c2 {
        1
    } else {
        2
    };

    // Bishop moves:
    // 0 if same square or unreachable (different colors),
    // 1 if they lie on the same diagonal,
    // 2 if same color but not same diagonal.
    let bishop = if r1 == r2 && c1 == c2 {
        0
    } else if (r1 - r2).abs() == (c1 - c2).abs() {
        1
    } else if (r1 + c1) % 2 == (r2 + c2) % 2 {
        2
    } else {
        0
    };

    // King moves:
    // Chebyshev distance = max(|Δrow|, |Δcol|)
    let king = (r1 - r2).abs().max((c1 - c2).abs());

    vec![rook, bishop, king]
}